target_years(tahun_anggaran) AS (
  VALUES ('2025'), ('2026')
)
INSERT INTO sikampung_data (
  tahun_anggaran,
  kode_desa,
  desa,
  distrik,
  kabupaten,
  iks,
  ike,
  ikl,
  nilai_idm,
  status_idm
)
SELECT
  target_years.tahun_anggaran,
  source.kode_desa,
  source.desa,
  source.distrik,
  source.kabupaten,
  source.iks,
  source.ike,
  source.ikl,
  source.nilai_idm,
  source.status_idm
FROM source
CROSS JOIN target_years
ON CONFLICT (tahun_anggaran, (LOWER(kode_desa)))
DO UPDATE SET
  desa = EXCLUDED.desa,
  distrik = EXCLUDED.distrik,
  kabupaten = EXCLUDED.kabupaten,
  iks = EXCLUDED.iks,
  ike = EXCLUDED.ike,
  ikl = EXCLUDED.ikl,
  nilai_idm = EXCLUDED.nilai_idm,
  status_idm = EXCLUDED.status_idm,
  updated_at = NOW();
